"use client";
/* Hops, from the Piixpal shadcn registry. Options: https://piixpal.dvkk.dev/components/ */
import * as React from "react";
import { loadPiixpal, piixAttrs, type PiixProps } from "@/lib/piixpal";

export function Hops(props: PiixProps) {
  React.useEffect(() => { loadPiixpal("hops"); }, []);
  return React.createElement("piix-sprite", { "name": "hops", ...piixAttrs(props) });
}

export default Hops;
